Object.assign(EV,{
 bretons1724:{y:1724,si:()=>S,tag:'Archive',an:'1724',nat:'Fait historique ; noms et chiffres d’après le Cercle généalogique de Bourbon.',t:'Les Bretons de Bourbon',
  b:'À Lorient, port de la Compagnie des Indes, des jeunes Bretons signent pour six ans comme soldats ou ouvriers de la Compagnie, puis embarquent pour Bourbon. Beaucoup y restent : forgerons, tailleurs, serruriers, taillandiers, puis chirurgiens, notaires, négociants. Le Cercle généalogique de Bourbon en a retrouvé 251 parmi les premiers émigrés : 62 du Finistère, 53 de Loire-Atlantique, 52 d’Ille-et-Vilaine, 48 du Morbihan, 36 des Côtes-d’Armor. Ils épousent des filles de l’île, et leurs noms sont encore portés aujourd’hui.',
  v:'De Lorient à Saint-Paul.',h:'Cercle généalogique de Bourbon, « Les premiers émigrés de Bretagne à La Réunion » (relevé de 2004). Exemples : Yves Goarzin, de Brest, arrivé en 1718, taillandier ; Jean Briant, engagé comme soldat à Lorient le 1ᵉʳ février 1724 ; Antoine François Chevalier, de Châtelaudren, engagé à Lorient en 1724 pour six ans ; Pierre Jacques Louis Augeard, de Dinan, chirurgien des vaisseaux (1782) ; François Pierre Chandemerle, de Quintin, notaire royal, député à l’Assemblée coloniale en 1791. Les arrivées relevées vont des années 1710 au début du XIXᵉ siècle.',o:[{n:'Continuer',d:'',fx:{},hist:1}]}});
// les colons nouveaux venus d'Europe portent parfois un nom de ces familles bretonnes (prénom du jeu + nom relevé)
{const np=nouvellePersonne;nouvellePersonne=function(o){const p=np.apply(this,arguments);try{if(p&&p.or==='eu'&&!p.bzh&&!/ /.test(p.n)&&Math.random()<.5){const r=BZH186[Math.floor(Math.random()*BZH186.length)];p.n=p.n+' '+r[0];p.bzh=(r[1]?r[1]+', ':'')+r[2]}}catch(e){}return p}}Object.assign(EV,{
 tessier1676:{y:1676,si:()=>S,tag:'Archive',an:'1676',nat:'Fait historique (généalogie).',t:'Noël Tessier, le premier Breton',
  b:'Un marin d’Elven, dans le Morbihan, débarque à Bourbon : Noël Tessier. Il a survécu au massacre de Fort-Dauphin, à Madagascar. En 1687, il épouse Anne Mousse, une fille de l’île de dix-neuf ans, alors que les mariages entre gens d’origines différentes sont interdits. Ils auront six filles et deux garçons, et soixante-cinq petits-enfants. Il meurt à Saint-Denis en 1721, à 79 ans.',
  v:'Le premier d’une longue lignée bretonne de l’île.',h:'Amicale Bretagne Réunion, « Noël Tessier, premier Breton arrivé à La Réunion en 1676 » (Raymond Figueras) ; Cercle généalogique de Bourbon.',o:[{n:'Continuer',d:'',fx:{},hist:1}]}});
Object.assign(EV,{
 macauliffe1900:{y:1900,si:()=>S,tag:'Archive',an:'1900',nat:'Fait historique.',t:'Le docteur Mac-Auliffe, à Cilaos',
  b:'Jean-Marie Mac-Auliffe, né à Rennes en 1837 dans une famille d’origine irlandaise, soigne dans l’île depuis 1863. Il a étudié la fièvre venue en 1865 : on la croyait typhus, c’était le paludisme. En 1900, le gouverneur le nomme médecin des Thermes de Cilaos ; il s’y installe pour de bon, pousse le cirque à s’ouvrir aux curistes, et publie en 1902 « Cilaos pittoresque et thermal ». Il meurt dans l’île en 1908.',
  v:'« Cilaos forever. »',h:'Amicale Bretagne Réunion, « Mac-Auliffe, Irlandais né à Rennes et figure de Cilaos » (d’après l’Office du tourisme de Cilaos, « Figures de Cilaos ») : né le 8 mars 1837 à Rennes, mort le 20 septembre 1908 ; premier poste en 1863 ; médecin des Thermes de Cilaos en 1900 ; « Cilaos pittoresque et thermal » (1902). Le paludisme ne sera éradiqué de l’île qu’en 1979.',o:[{n:'Continuer',d:'',fx:{},hist:1}]}});
Object.assign(EV,{
 femmesMarronnes:{y:1753,si:()=>S,tag:'Archive',an:'1753',nat:'Fait historique ; la part de légende est impossible à séparer pour plusieurs de ces femmes.',t:'Les femmes marronnes',
  b:'Les détachements tuent les hommes pris dans les camps ; ils ramènent plutôt les femmes, parce qu’elles peuvent dire où sont les autres camps. Pourtant ce sont souvent elles qui préparent la fuite des hommes et les rejoignent ensuite, qui gardent les chants, les remèdes, la cuisine et la connaissance des plantes. Les noms ont traversé le temps : Raharianne, tuée avec Mafac à la Rivière des Galets ; Sarlave, compagne de Laverdure ; Simangalove, guerrière et conseillère de Matouté, à Cilaos ; Héva, la compagne d’Anchaing, dont aucune archive ne parle.',
  v:'On se souvient des chefs ; les femmes tenaient le camp.',h:'Portail de l’esclavage de La Réunion, « Les femmes marronnes à La Réunion » (documents des Archives départementales de 1743, 1751, 1752, 1753 ; Marie-Ange Payet, « Les femmes dans le marronnage à l’île de la Réunion de 1662 à 1848 », 2013). Héva relève du mythe fondateur ; Simangalove est connue par Leal ; Raharianne est attestée en 1751.',o:[{n:'Continuer',d:'',fx:{},hist:1}]},
 adzire1846:{y:1846,si:()=>S,tag:'Archive',an:'1846',nat:'Fait historique (rapports de police) ; son histoire a ensuite été romancée.',t:'Adzire, qui nourrissait les marrons',
  b:'Des rapports de police signalent une femme, Adzire, accusée de ravitailler les marrons dans les Hauts. Deux ans avant l’abolition, le marronnage continue, et ceux qui restent en bas l’aident en secret.',
  v:'Le marronnage vit aussi grâce à ceux qui restent.',h:'Portail de l’esclavage de La Réunion, « Les femmes marronnes à La Réunion » : rapports de police de 1846 ; histoire romancée plus tard par Firmin Lacpatia.',o:[{n:'Continuer',d:'',fx:{},hist:1}]}});
